    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            v=grid[r][c]
            if v not in (0,3) and all(grid[a][b]==3 for a,b in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))): centers.append((r,c,v))
    # Preserve only cross marker cells; all other ray intersections resolve in center enumeration order.
    for r,c,v in centers:
        for j in range(w):
            if grid[r][j]!=3: out[r][j]=v
        for i in range(h):
            if grid[i][c]!=3: out[i][c]=v
    return out
