def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    centers=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v not in (0,3) and 0<r<h-1 and 0<c<w-1 and all(grid[a][b]==3 for a,b in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))): centers.append((r,c,v))
    # Paint horizontal rays, skipping the center's adjacent arms and stopping at the next cross; then vertical rays.
    for r,c,v in centers:
        for dc in (-1,1):
            cc=c+dc
            if 0<=cc<w and grid[r][cc]==3: cc+=dc
            while 0<=cc<w and grid[r][cc]!=3:
                out[r][cc]=v; cc+=dc
    for r,c,v in centers:
        for dr in (-1,1):
            rr=r+dr
            if 0<=rr<h and grid[rr][c]==3: rr+=dr
            while 0<=rr<h and grid[rr][c]!=3:
                out[rr][c]=v; rr+=dr
    return out

